// Link previously-defined species to their newly-added Mega forms.
const _RETRO_MEGAS: Record<string, string> = {
  Aerodactyl: "Aerodactyl-Mega", Aggron: "Aggron-Mega", Manectric: "Manectric-Mega",
  Banette: "Banette-Mega", Glalie: "Glalie-Mega", Sharpedo: "Sharpedo-Mega",
  Camerupt: "Camerupt-Mega", Altaria: "Altaria-Mega", Ampharos: "Ampharos-Mega",
  Steelix: "Steelix-Mega", Houndoom: "Houndoom-Mega", Kangaskhan: "Kangaskhan-Mega",
  Pinsir: "Pinsir-Mega", Tyranitar: "Tyranitar-Mega", Scizor: "Scizor-Mega",
  Gyarados: "Gyarados-Mega", Heracross: "Heracross-Mega", Slowbro: "Slowbro-Mega",
  Sableye: "Sableye-Mega",
};
for (const [base, mega] of Object.entries(_RETRO_MEGAS)) {
  if (SPECIES[base] && !SPECIES[base].megaForm) SPECIES[base].megaForm = mega;
}

// Showdown sprite URL helper — returns an animated GIF of the Pokémon
export function getSpriteUrl(speciesName: string): string {
  const sp = SPECIES[speciesName];
  if (sp?.image) return sp.image;
  const slug = speciesName
    .toLowerCase()
    .replace(/\s*\(.*?\)\s*/g, "")
    .replace(/[^a-z0-9-]/g, "")
    .replace(/-mega-([xy])$/, "-mega$1");
  return `https://play.pokemonshowdown.com/sprites/ani/${slug}.gif`;
}

// Cleanup: the inline `in MOVES` ternaries above run at module load and resolve
// to fallbacks if the moves aren't defined. Patch unresolved move references.
for (const sp of Object.values(SPECIES)) {
  sp.moves = sp.moves.map((m) => (MOVES[m] ? m : "Tackle"));
}

